import{_ as a,o as n,c as e,am as i}from"./chunks/framework._FJXuPhs.js";const k=JSON.parse('{"title":"安装 Docker 服务","description":"","frontmatter":{"title":"安装 Docker 服务","excerpt":"摘要","date":"2026-02-27 20:51:31","updated":"2026-02-27 20:51:31"},"headers":[],"relativePath":"部署&工具/Java 知识体系-容器部署/Docker 基础/Docker的下载和安装/安装 Docker 服务.md","filePath":"部署&工具/Java 知识体系-容器部署/Docker 基础/Docker的下载和安装/安装 Docker 服务.md","lastUpdated":null}'),p={name:"部署&工具/Java 知识体系-容器部署/Docker 基础/Docker的下载和安装/安装 Docker 服务.md"};function t(l,s,o,c,d,r){return n(),e("div",null,[...s[0]||(s[0]=[i(`<p>系统选择的是 CentOS 8.5</p><p>Docker 服务安装命令</p><h3 id="_1、安装必要的依赖工具" tabindex="-1">1、安装必要的依赖工具 <a class="header-anchor" href="#_1、安装必要的依赖工具" aria-label="Permalink to &quot;1、安装必要的依赖工具&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo yum install -y yum-utils device-mapper-persistent-data lvm2</span></span></code></pre></div><p>作用说明：</p><ul><li><code>yum-utils</code>：提供 <code>yum-config-manager</code></li><li><code>device-mapper-persistent-data</code>：Docker 存储驱动依赖</li><li><code>lvm2</code>：逻辑卷管理支持</li></ul><h3 id="_2、添加-docker-官方-yum-仓库" tabindex="-1">2、添加 Docker 官方 YUM 仓库 <a class="header-anchor" href="#_2、添加-docker-官方-yum-仓库" aria-label="Permalink to &quot;2、添加 Docker 官方 YUM 仓库&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo yum-config-manager --add-repo https://download.docker.com/linux/centos/docker-ce.repo</span></span></code></pre></div><p>执行后，系统会新增 Docker 官方仓库地址，后续可直接使用 <code>yum</code> 安装 Docker</p><h3 id="_3、安装-docker-服务" tabindex="-1">3、安装 Docker 服务 <a class="header-anchor" href="#_3、安装-docker-服务" aria-label="Permalink to &quot;3、安装 Docker 服务&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo yum install -y docker-ce docker-ce-cli containerd.io</span></span></code></pre></div><p>各组件说明：</p><ul><li><code>docker-ce</code>：Docker 引擎核心服务</li><li><code>docker-ce-cli</code>：Docker 命令行工具</li><li><code>containerd.io</code>：容器运行时（Docker 底层依赖）</li></ul><p>这里安装有点问题，还是需要执行下面的第一步（网络问题）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 将这个地址添加到系统的软件源列表中，以便可以安装Docker。</span></span>
<span class="line"><span>yum-config-manager --add-repo http://mirrors.aliyun.com/docker-ce/linux/centos/docker-ce.repo</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#用于安装Docker相关的软件包</span></span>
<span class="line"><span>sudo yum install -y docker-ce docker-ce-cli containerd.io</span></span></code></pre></div><h3 id="_4、启动-docker-服务" tabindex="-1">4、启动 Docker 服务 <a class="header-anchor" href="#_4、启动-docker-服务" aria-label="Permalink to &quot;4、启动 Docker 服务&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#启动服务</span></span>
<span class="line"><span>sudo systemctl start docker</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#设置开机自启</span></span>
<span class="line"><span>sudo systemctl enable docker</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#验证是否安装成功</span></span>
<span class="line"><span>docker --version</span></span></code></pre></div><h3 id="_5、docker-配置镜像源" tabindex="-1">5、Docker 配置镜像源 <a class="header-anchor" href="#_5、docker-配置镜像源" aria-label="Permalink to &quot;5、Docker 配置镜像源&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo mkdir -p /etc/docker</span></span>
<span class="line"><span>sudo tee /etc/docker/daemon.json &gt; /dev/null &lt;&lt; &#39;EOF&#39;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;registry-mirrors&quot;: [</span></span>
<span class="line"><span>    &quot;https://mirror.iscas.ac.cn&quot;,</span></span>
<span class="line"><span>    &quot;https://dockerproxy.com&quot;,</span></span>
<span class="line"><span>    &quot;https://docker.m.daocloud.io&quot;,</span></span>
<span class="line"><span>    &quot;https://docker.nju.edu.cn&quot;,</span></span>
<span class="line"><span>    &quot;https://docker.mirrors.sjtug.sjtu.edu.cn&quot;,</span></span>
<span class="line"><span>    &quot;https://docker.rainbond.cc&quot;</span></span>
<span class="line"><span>  ]</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>EOF</span></span></code></pre></div><p>Docker的镜像源配置保存在 <code>daemon.json</code> 文件中。你可以直接查看这个文件的内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cat /etc/docker/daemon.json</span></span></code></pre></div><p>使用命令行查看（验证方法）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker info | grep -A 5 &quot;Registry Mirrors&quot;</span></span></code></pre></div><p>重启服务</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo systemctl daemon-reexec</span></span>
<span class="line"><span>sudo systemctl restart docker</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#查看配置</span></span>
<span class="line"><span>docker info | grep -A 10 &quot;Registry Mirrors&quot;</span></span></code></pre></div><h2 id="_7、🚀-优化建议-精简镜像源" tabindex="-1">7、🚀 优化建议：精简镜像源 <a class="header-anchor" href="#_7、🚀-优化建议-精简镜像源" aria-label="Permalink to &quot;7、🚀 优化建议：精简镜像源&quot;">​</a></h2><p><strong>镜像源过多</strong>：配置了 6 个镜像源，Docker 会按顺序尝试，反而可能拖慢速度</p><p><strong>不要配置太多镜像源</strong>，建议只保留 1-2 个最快的。推荐组合：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/docker/daemon.json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/null</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;EOF&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;registry-mirrors&quot;: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;https://docker.mirrors.sjtug.sjtu.edu.cn&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;https://docker.m.daocloud.io&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 重启服务</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span></span></code></pre></div>`,29)])])}const u=a(p,[["render",t]]);export{k as __pageData,u as default};
